 function updateScopeField(id,scope){const node=$(id);if(!node)return;const choices=scopeChoices(scope),value=node.value;node.outerHTML=choices?`<select id="${id}">${choices.map(([key,text])=>`<option value="${esc(key)}" ${key===value?'selected':''}>${esc(text)}</option>`).join('')}</select>`:`<input id="${id}" value="${esc(value)}" maxlength="100" placeholder="填写明确渠道标识">`;}
