   const summary=event.target.closest?.('[data-employee-summary-operator]');if(summary){$('employeeOperator').value=summary.dataset.employeeSummaryOperator;page=1;load();return;}
   const row=event.target.closest?.('[data-employee-detail]');if(row){openEmployee(row.dataset.employeeDetail,row.dataset.employeeEvidence||'',row.dataset.employeeOperatorDetail||'',true,Object.hasOwn(row.dataset,'employeeCardState')?row.dataset.employeeCardState:null);return;}
