   const ledgerFilter=event.target.closest?.('[data-employee-detail-ledger-state]');if(ledgerFilter){setDetailCardState(ledgerFilter.dataset.employeeDetailLedgerState);return;}
   const evidence=event.target.closest?.('[data-employee-show-evidence]');if(evidence){$('employeeEvidenceHost').innerHTML=evidenceMarkup(evidence.dataset.employeeShowEvidence);return;}
   const operator=event.target.closest?.('[data-employee-operator-evidence]');if(operator){$('employeeEvidenceHost').innerHTML=evidenceMarkup('estimated_available',operator.dataset.employeeOperatorEvidence);return;}
   const applicationEdit=event.target.closest?.('[data-employee-application-edit]');if(applicationEdit){openAction('application',detail?.employee?.id||'',applicationEdit.dataset.employeeApplicationEdit);return;}
